// Idempotency guard
if (document.getElementById('cta-contact-btn')) return;

const btn = document.createElement('a');
btn.id = 'cta-contact-btn';
btn.href = 'https://support.fandom.com/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';
btn.target = '_self';
btn.textContent = '📬  Contact Us — Submit a Request';

btn.style.cssText = `
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 14px 0 4px 0;
  padding: 13px 28px;
  background: linear-gradient(135deg, #e9502b 0%, #c0392b 100%);
  color: #fff !important;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-decoration: none !important;
  border-radius: 8px;
  box-shadow: 0 4px 14px rgba(192,57,43,0.40);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  cursor: pointer;
`;

btn.addEventListener('mouseenter', () => {
  btn.style.transform = 'translateY(-2px)';
  btn.style.boxShadow = '0 7px 20px rgba(192,57,43,0.55)';
});
btn.addEventListener('mouseleave', () => {
  btn.style.transform = 'translateY(0)';
  btn.style.boxShadow = '0 4px 14px rgba(192,57,43,0.40)';
});

// Insert the button right after the <h1>
const h1 = element.querySelector('h1.article-title');
if (h1 && h1.parentNode) {
  h1.insertAdjacentElement('afterend', btn);
}

// Replace the inline "click here" text with something clearer and visually distinct
element.textContent = 'submit a help desk request';
element.style.cssText = `
  color: #c0392b;
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
`;
